import Image from "next/image";

export type DitheredProps = {
  className?: string;
  style?: React.CSSProperties;
  /** `eager` for illustrations in the first screen, so they never count as a late LCP image. */
  loading?: "eager" | "lazy";
};

type Props = DitheredProps & { src: string; width: number; height: number };

/**
 * A 1-bit dithered illustration (generated by scripts/prepare-assets.mjs).
 * Served unoptimised: lossy re-encoding would smear the dither pattern.
 * Purely decorative, so it's hidden from assistive technology.
 */
export function Dithered({ src, width, height, className = "", style, loading }: Props) {
  return (
    <Image
      src={src}
      width={width}
      height={height}
      alt=""
      aria-hidden="true"
      unoptimized
      loading={loading}
      className={`px h-auto ${className}`}
      style={style}
    />
  );
}
